update sdsshop.u_p_productionmaterial
   set returnedqty = returnedqty + #{returnQty}
 where shop_code = #{shopCode} and materialcode = #{materialCode}
   and actualqty + returnedqty + #{returnQty} <= pickedqty

update sdsshop.u_p_productionmaterial
   set pickedqty = pickedqty + #{pickQty}
 where shop_code = #{shopCode} and materialcode = #{materialCode}
   and pickedqty + #{pickQty} <= totalqty
